pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount, address ownerAddr) public {
        vm.assume(ownerAddr != address(0));
        vm.assume(burnAmount > 0);
        vm.deal(ownerAddr, 0);
        vm.prank(ownerAddr);
        c.owned();
        // Give the owner enough balance to burn
        vm.prank(ownerAddr);
        c.mintToken(ownerAddr, burnAmount);
        // Call burn as the owner
        vm.prank(ownerAddr);
        c.burn(burnAmount);
        // Assert: owner is still the one who called owned (the original msg.sender), not address(0)
        assertTrue(c.owner() == ownerAddr);
    }
}

