pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address burner, uint256 amount) public {
        vm.assume(amount > 0 && amount <= type(uint256).max / 2);
        vm.assume(burner != address(0));
        vm.deal(burner, 0);
        // Let burner become owner by exploiting the missing onlyOwner modifier
        vm.prank(burner);
        c.owned();
        // Mint tokens to burner so it can burn
        vm.prank(address(c).balance == 0 ? burner : address(0)); // No effect, burner is now owner
        c.mintToken(burner, amount);
        uint256 supplyBefore = c.totalSupply();
        uint256 burnerBalBefore = c.balanceOf(burner);
        vm.prank(burner);
        c.burn(amount);
        uint256 supplyAfter = c.totalSupply();
        uint256 burnerBalAfter = c.balanceOf(burner);
        assertTrue(supplyBefore - amount == supplyAfter && burnerBalBefore - amount == burnerBalAfter);
    }
}

