import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // 1. Restrict burn amount to non-zero and within balance of msg.sender (owner after minting)
        vm.assume(burnAmount > 0);
        // Owner mints tokens to themselves so they have balance to burn
        vm.prank(address(this));
        c.mintToken(address(this), burnAmount);
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        // 2. Owner burns the exact amount they just minted
        vm.prank(address(this));
        c.burn(burnAmount);
        // 3. Assert that totalSupply decreased by exactly the burned amount
        assertTrue(c.totalSupply() == supplyBefore - burnAmount);
    }
}

